package com.slotix.reservationcore.policy;import com.slotix.reservationcore.common.*;import org.springframework.http.*;import org.springframework.stereotype.*;import org.springframework.transaction.annotation.*;import org.springframework.web.server.*;import java.util.*;
@Service public class BookingPolicyService{final BookingPolicyRepository repo;final TenantAccessService access;public BookingPolicyService(BookingPolicyRepository r,TenantAccessService a){repo=r;access=a;}@Transactional public UUID create(UUID c,CreateBookingPolicyRequest q){access.requireActiveMembership(c);if(q.maxDurationMinutes()<q.minDurationMinutes()||q.minDurationMinutes()%q.slotIncrementMinutes()!=0||q.maxDurationMinutes()%q.slotIncrementMinutes()!=0)throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,"Policy durations must align with the slot increment");return repo.save(BookingPolicy.create(c,q.name().trim(),q.minDurationMinutes(),q.maxDurationMinutes(),q.slotIncrementMinutes(),q.minNoticeMinutes(),q.maxAdvanceDays(),q.cancellationNoticeMinutes(),q.approvalRequired(),q.allowCustomerCancel())).getId();}}
